#include <iostream>
#include <vector>
#include <cassert>
using namespace std;

struct MatrixData {
    int height, width;
    vector<long long> data;
    MatrixData(int r=0,int c=0):height(r),width(c),data(r*c){}
    long long& element(int r,int c){return data[r*width+c];}
    long long element(int r,int c)const{return data[r*width+c];}
    MatrixData& add(const MatrixData& m){
        assert(height==m.height && width==m.width);
        for(int i=0;i<height*width;++i)data[i]+=m.data[i];
        return *this;
    }
    MatrixData& subtract(const MatrixData& m){
        assert(height==m.height && width==m.width);
        for(int i=0;i<height*width;++i)data[i]-=m.data[i];
        return *this;
    }
    MatrixData& multiply(const MatrixData& m){
        assert(width==m.height);
        MatrixData res(height,m.width);
        for(int i=0;i<height;++i){
            for(int j=0;j<m.width;++j){
                for(int k=0;k<width;++k){
                    res.element(i,j)+=element(i,k)*m.element(k,j)%mod;
                }
                res.element(i,j)%=mod;
            }
        }
        *this=res;
        return *this;
    }
    static MatrixData identity(int n){
        MatrixData res(n,n);
        for(int i=0;i<n;++i)res.element(i,i)=1;
        return res;
    }
    static MatrixData power(MatrixData a,int n){
        assert(a.height==a.width);
        MatrixData res=identity(a.height);
        while(n){
            if(n&1)res.multiply(a);
            a.multiply(a);
            n>>=1;
        }
        return res;
    }
};

vector<MatrixData> mats(65);
long long compute(int i,int k){
    return MatrixData::power(mats[i+k],k-i)*MatrixData::power(mats[i],i);
}

long long execute(long long n,long long k){
    long long count=0,tmp=n;
    while(tmp){tmp/=k;++count;}
    vector<MatrixData> b(count+5),c(count+5),d(k+1);
    b[0]=mats[k-1];
    c[0]=MatrixData::power(b[0],k-1);
    b[1]=compute(k-1,k);
    c[1]=MatrixData::power(b[1],k-1);
    MatrixData s=MatrixData::identity(2*k+1);
    for(int j=2;j<=count+1;++j){
        b[j]=compute(k-j%k,k);
        s*=c[j-1];
        b[j]*=s;
        c[j]=MatrixData::power(b[j],k-1);
    }
    int idx=1,rem=n%k;
    n-=rem;
    int q=0;
    long long tmp2=n;
    if(tmp2){while(tmp2%k==0){++q;tmp2/=k;}}
    q=(k-q%k)%k;
    MatrixData ans=MatrixData::identity(2*k+1);
    ans=MatrixData::power(mats[q],rem)*MatrixData::power(mats[q+k],max(rem-q,0));
    n/=k;
    if(n==0){return (ans.element(2*k,0)+ans.element(0,0))%mod;}
    --n;
    while(n){
        int t=n%k;
        if(t){ans*=MatrixData::power(b[idx],t);}
        n/=k;++idx;
    }
    ans*=b[1];
    return (ans.element(2*k,0)+ans.element(0,0))%mod;
}

int main(){
    long long n,k;
    cin>>n>>k;
    for(int i=0;i<=2*k;++i){
        mats[i]=MatrixData(2*k+1);
        for(int j=0;j<i;++j)mats[i].element(0,j)=1;
        for(int j=0;j<2*k-1;++j)mats[i].element(j+1,j)=1;
        mats[i].element(2*k,0)=1;
        mats[i].element(2*k,2*k)=1;
    }
    cout<<execute(n,k)<<endl;
    return 0;
}
